function findLonely(nums) {
  const result = [];
  for (let i = 0; i < nums.length; i++) {
    let ok = true;
    for (let j = 0; j < nums.length; j++) {
      if (j === i) continue;
      if (Math.abs(nums[j] - nums[i]) <= 1) { ok = false; break; }
    }
    if (ok) result.push(nums[i]);
  }
  return result;
}

