function generate(rand, size) {
  if (size === 'large') {
    const nums = [];
    for (let i = 0; i < 2000; i++) {
      nums.push(rand() < 0.5 ? Math.floor(rand() * 1000001) : Math.floor(rand() * 3000));
    }
    return [nums];
  }
  const n = 1 + Math.floor(rand() * 10);
  const edge = rand() < 0.2;
  const nums = Array.from({ length: n }, () => {
    const v = Math.floor(rand() * 16);
    return edge && rand() < 0.4 ? 1000000 - (v % 3) : v;
  });
  return [nums];
}
